#include <bits/stdc++.h>
#include <gmpxx.h>
#include "validate.cpp"
using I=__int128_t;
struct Local {uint32_t support;vector<int> sites;vector<vector<pair<uint16_t,int32_t>>> rows;int vacuum;};
struct Emb {int block;uint32_t mask;array<unsigned char,5> sites;};
struct Indexed {vector<Local> blocks;vector<Emb> embeddings;array<vector<int>,32> incidence;map<uint32_t,int64_t> vacuum_poly;array<vector<pair<uint32_t,int64_t>>,32> vacindex;int64_t constant=0;uint64_t records=0;int stabilized=0;};
vector<array<int,6>> pairs6;int adjmat[32][32],orbit[32][32];array<int64_t,14> cm{};using Channels=array<int64_t,15>;unordered_map<uint32_t,Channels> lazy;
uint64_t lookups=0,misses=0,peakcache=0;double lookup_seconds=0;size_t max_limb=0;long long chooseN[33][7];int gram6[15][15];double gmp_cpu=0;uint64_t gmp_products=0;
void matching(vector<int> left,array<int,6> a,int pos){if(pos==6){pairs6.push_back(a);return;}for(int j=1;j<(int)left.size();j++){a[pos]=left[0];a[pos+1]=left[j];vector<int> rest;for(int k=1;k<(int)left.size();k++)if(k!=j)rest.push_back(left[k]);matching(rest,a,pos+2);}}
Channels analytic(uint32_t mask){array<int,6> s{};int n=0;for(int i=0;i<32;i++)if(mask>>i&1)s[n++]=i;assert(n==6);Channels out{};for(int p=0;p<15;p++){int edge[3],orb[3];for(int k=0;k<3;k++){int a=s[pairs6[p][2*k]],b=s[pairs6[p][2*k+1]];edge[k]=adjmat[a][b];orb[k]=orbit[a][b];}for(int k=0;k<3;k++)out[p]+=2LL*edge[(k+1)%3]*edge[(k+2)%3]*cm[orb[k]];}return out;}
const Channels& source(uint32_t mask){lookups++;auto it=lazy.find(mask);if(it!=lazy.end())return it->second;misses++;if(lazy.size()>=16384)lazy.clear();auto inserted=lazy.emplace(mask,analytic(mask));peakcache=max<uint64_t>(peakcache,lazy.size());return inserted.first->second;}
int64_t amplitude(uint64_t state,uint32_t mask){const auto&a=source(mask);array<int,6> colors{};int n=0;for(int i=0;i<32;i++)if(mask>>i&1)colors[n++]=(state>>(2*i))&3;assert(n==6);int64_t x=0;for(int p=0;p<15;p++){bool equal=true;for(int k=0;k<6;k+=2)equal&=colors[pairs6[p][k]]==colors[pairs6[p][k+1]];if(equal)x+=a[p];}return x;}
mpz_class big(I a){bool neg=a<0;__uint128_t u=neg?-__uint128_t(a):__uint128_t(a);uint64_t words[2]={uint64_t(u),uint64_t(u>>64)};mpz_class z;mpz_import(z.get_mpz_t(),2,-1,sizeof(uint64_t),0,0,words);if(neg)z=-z;return z;}
void physical_edge(){using C=complex<int>;array<array<C,4>,4> rung{};rung[0][1]=1;rung[0][2]=-1;rung[1][3]=1;rung[1][0]=-1;rung[2][0]=C(0,1);rung[2][3]=C(0,1);rung[3][1]=1;rung[3][2]=1;array<array<C,16>,16>B{};for(int j=0;j<4;j++)for(int i=0;i<4;i++)for(int x=0;x<4;x++)for(int y=0;y<4;y++)B[i+4*j][x+4*y]=rung[i][x]*rung[j][y];auto swapbit=[](int s,int i,int j){return s^((((s>>i)&1)^((s>>j)&1))*((1<<i)|(1<<j)));};for(int col=0;col<16;col++){array<C,16> z{};for(int s=0;s<16;s++){z[swapbit(s,0,2)]+=B[col][s];z[swapbit(s,1,3)]+=B[col][s];z[s]-=B[col][s];}map<int,int> expected;for(int o=0;o<3;o++)for(auto[t,c]:rule::act(col,rule::letter(o,0,1)))expected[t]+=c;for(int row=0;row<16;row++){C value=0;for(int s=0;s<16;s++)value+=conj(B[row][s])*z[s];assert(value==C(4*expected[row],0));}}}
void probes(){for(int p=0;p<15;p++){array<int,6> colors{};for(int k=0;k<3;k++)colors[pairs6[p][2*k]]=colors[pairs6[p][2*k+1]]=k+1;for(int q=0;q<15;q++){int z=1;for(int k=0;k<6;k+=2)z*=colors[pairs6[q][k]]==colors[pairs6[q][k+1]];assert(z==(p==q));}}}
Indexed compile_index(string family,string dir){Indexed idx;rule::Stats stat;rule::canonicalize=true;auto motifs=rule::motifs(family,stat,true);ofstream bin(dir+"/rules_"+family+".bin",ios::binary);for(auto &[sup,p]:motifs){Local b;b.support=sup;for(int i=0;i<32;i++)if(sup>>i&1)b.sites.push_back(i);int n=b.sites.size();auto mat=rule::wordmatrix(rule::localize(p,sup),n);auto before=rule::productmatrix(rule::localize(rule::raw_polynomials[sup],sup),n);assert(mat==before);b.rows.resize(1<<(2*n));b.vacuum=0;for(auto[key,c]:mat){assert(c>=INT32_MIN&&c<=INT32_MAX);int src=key>>10,dst=key&1023;if(src==0&&dst==0)b.vacuum=c;else b.rows[dst].push_back({uint16_t(src),int32_t(c)});}rule::serialize(bin,sup,mat,n,stat);idx.records+=mat.size();int stabilizers=0;rule::Matrix stabmatrix;for(int t=0;t<32;t++){uint32_t shifted=0;for(int site:b.sites)shifted|=1u<<rule::translate(site,t);if(shifted!=sup)continue;stabilizers++;for(auto[key,c]:mat){int src=key>>10,dst=key&1023,ns=0,nd=0;for(int i=0;i<n;i++){int j=find(b.sites.begin(),b.sites.end(),rule::translate(b.sites[i],t))-b.sites.begin();ns|=((src>>(2*i))&3)<<(2*j);nd|=((dst>>(2*i))&3)<<(2*j);}stabmatrix[(ns<<10)|nd]+=c;}}if(stabilizers>1){assert(stabilizers==4);idx.stabilized++;}if(family!="N")for(auto[key,c]:stabmatrix)assert(stabmatrix[((key&1023)<<10)|(key>>10)]==c);int bi=idx.blocks.size();idx.blocks.push_back(move(b));for(int t=0;t<32;t++){Emb e{};e.block=bi;for(int i=0;i<n;i++){e.sites[i]=rule::translate(idx.blocks.back().sites[i],t);e.mask|=1u<<e.sites[i];}int ei=idx.embeddings.size();idx.embeddings.push_back(e);for(int i=0;i<n;i++)idx.incidence[e.sites[i]].push_back(ei);if(idx.blocks.back().vacuum){for(uint32_t sub=e.mask;;sub=(sub-1)&e.mask){idx.vacuum_poly[sub]+=idx.blocks.back().vacuum*(__builtin_popcount(sub)%2?-1:1);if(!sub)break;}}}rule::checkpoint(family+"_cartesian_compile",stat);rule::guard();}assert(idx.stabilized==1);for(auto[m,c]:idx.vacuum_poly)if(c){if(!m)idx.constant=c;else idx.vacindex[__builtin_ctz(m)].push_back({m,c});}return idx;}
struct Count{uint64_t incidence_visits=0,embedding_hits=0,row_hits=0,rule_hits=0,vac_visits=0,vac_hits=0,source_calls=0,source_misses=0;};
array<I,15> indexed_action(const Indexed&idx,const array<int,6>&s,Count&count){uint32_t mask=0;for(int a:s)mask|=1u<<a;vector<int> embeds;for(int site:s)for(int e:idx.incidence[site]){count.incidence_visits++;if(__builtin_ctz(idx.embeddings[e].mask&mask)==site)embeds.push_back(e);}count.embedding_hits+=embeds.size();int64_t vacuum=idx.constant;for(int site:s)for(auto[m,c]:idx.vacindex[site]){count.vac_visits++;if((m&mask)==m){count.vac_hits++;vacuum+=c;}}// Independent empty-embedding count, bounded geometry only (not transition scanning).
 int64_t vacuum_direct=0;for(const auto&e:idx.embeddings)if(!(e.mask&mask))vacuum_direct+=idx.blocks[e.block].vacuum;assert(vacuum==vacuum_direct);
 auto initial=source(mask);array<I,15> out{};for(int p=0;p<15;p++){uint64_t target=0;for(int k=0;k<3;k++)for(int j=0;j<2;j++)target|=uint64_t(k+1)<<(2*s[pairs6[p][2*k+j]]);out[p]=I(vacuum)*initial[p];for(int ei:embeds){const auto&e=idx.embeddings[ei];const auto&b=idx.blocks[e.block];uint16_t local=0;uint64_t base=target;uint32_t basemask=mask&~e.mask;for(int i=0;i<(int)b.sites.size();i++){int a=e.sites[i];local|=((target>>(2*a))&3)<<(2*i);base&=~(3ULL<<(2*a));}const auto&row=b.rows[local];if(!row.empty())count.row_hits++;for(auto[src,c]:row){count.rule_hits++;uint64_t state=base;uint32_t source_mask=basemask;for(int i=0;i<(int)b.sites.size();i++){int color=(src>>(2*i))&3,a=e.sites[i];state|=uint64_t(color)<<(2*a);if(color)source_mask|=1u<<a;}out[p]+=I(c)*amplitude(state,source_mask);}}}return out;}
array<int,6> unrank(uint64_t rank){array<int,6>s{};s[0]=0;int top=30;for(int k=5;k>=1;k--){while(chooseN[top][k]>long(rank))top--;s[k]=top+1;rank-=chooseN[top][k];top--;}return s;}
int main(int argc,char**argv){assert(argc==2);string dir=argv[1];rule::outdir=dir;rule::deadline=55.;physical_edge();matching({0,1,2,3,4,5},{},0);probes();for(int p=0;p<15;p++)for(int q=0;q<15;q++){int root[6];iota(root,root+6,0);function<int(int)> find=[&](int x){return root[x]==x?x:root[x]=find(root[x]);};for(auto pair:{pairs6[p],pairs6[q]})for(int k=0;k<6;k+=2)root[find(pair[k])]=find(pair[k+1]);int v=1;for(int i=0;i<6;i++)if(find(i)==i)v*=3;gram6[p][q]=v;}for(int n=0;n<=32;n++){chooseN[n][0]=1;for(int k=1;k<=6;k++)chooseN[n][k]=n?chooseN[n-1][k-1]+chooseN[n-1][k]:0;}int nr,d,ne;ifstream geo(dir+"/../geometry_8x4.txt");geo>>nr>>d>>ne;assert(nr==32&&d==14);for(int k=0;k<ne;k++){int a,b,w;geo>>a>>b>>w;adjmat[a][b]=adjmat[b][a]=w;}for(int i=0;i<32;i++)for(int j=i+1;j<32;j++)geo>>orbit[i][j],orbit[j][i]=orbit[i][j];ifstream coeff(dir+"/../reference_coefficients.txt");int64_t skip;for(int j=0;j<14;j++)coeff>>skip;for(int j=0;j<14;j++)coeff>>cm[j];assert(geo&&coeff);ofstream lb(dir+"/lookup_benchmark.json");double lstart=rule::cpu();int64_t lsum=0;for(int i=0;i<512;i++){auto sites=unrank(uint64_t(i)*169910/511);uint32_t mask=0;for(int a:sites)mask|=1u<<a;lsum+=source(mask)[i%15];}double cold=rule::cpu()-lstart;lstart=rule::cpu();for(int r=0;r<8;r++)for(int i=0;i<512;i++){auto sites=unrank(uint64_t(i)*169910/511);uint32_t mask=0;for(int a:sites)mask|=1u<<a;lsum+=source(mask)[i%15];}double warm=rule::cpu()-lstart;lb<<"{\"cold_calls\":512,\"cold_seconds\":"<<cold<<",\"warm_calls\":4096,\"warm_seconds\":"<<warm<<",\"checksum\":\""<<lsum<<"\"}";lb.close();lazy.clear();char *args[]={argv[0],argv[1]};int check=validation_main(2,args);assert(check==0);double validated=rule::cpu();rule::graph(8,4);ofstream report(dir+"/sample.jsonl");ofstream summary(dir+"/summary.json");summary<<"{\"validation_cpu_seconds\":"<<validated<<",\"families\":[";bool first=true;try{for(string fam:{"N","F","L"}){double setupstart=rule::cpu();auto idx=compile_index(fam,dir);double setup=rule::cpu()-setupstart;lazy.clear();lookups=misses=peakcache=0;Count total;gmp_cpu=0;gmp_products=0;mpz_class checksum=0;uint64_t maxhits=0;double maxseconds=0;map<int,int> classes;double start=rule::cpu();int completed=0;for(int sample=0;sample<512;sample++){if(rule::cpu()>53.)break;auto s=unrank(uint64_t(sample)*169910/511);uint32_t mask=0;for(int a:s)mask|=1u<<a;int internal=0;for(int i=0;i<6;i++)for(int j=i+1;j<6;j++)internal+=adjmat[s[i]][s[j]];classes[internal]++;Count c;uint64_t oldlook=lookups,oldmiss=misses;double ts=rule::cpu();auto result=indexed_action(idx,s,c);double sec=rule::cpu()-ts;auto input=analytic(mask);mpz_class dot=0;double gs=rule::cpu();for(int p=0;p<15;p++){auto z=big(result[p]);max_limb=max(max_limb,mpz_size(z.get_mpz_t()));for(int q=0;q<15;q++)if(input[q]&&result[p]){dot+=z*input[q]*gram6[p][q];gmp_products++;}}gmp_cpu+=rule::cpu()-gs;checksum+=dot;c.source_calls=lookups-oldlook;c.source_misses=misses-oldmiss;maxhits=max(maxhits,c.rule_hits);maxseconds=max(maxseconds,sec);total.incidence_visits+=c.incidence_visits;total.embedding_hits+=c.embedding_hits;total.row_hits+=c.row_hits;total.rule_hits+=c.rule_hits;total.vac_visits+=c.vac_visits;total.vac_hits+=c.vac_hits;report<<"{\"family\":\""<<fam<<"\",\"sample\":"<<sample<<",\"mask\":"<<mask<<",\"occupied_edges\":"<<internal<<",\"incidence_visits\":"<<c.incidence_visits<<",\"embedding_hits\":"<<c.embedding_hits<<",\"row_hits\":"<<c.row_hits<<",\"rule_hits\":"<<c.rule_hits<<",\"lookup_calls\":"<<c.source_calls<<",\"lookup_misses\":"<<c.source_misses<<",\"cpu_seconds\":"<<sec<<"}\n";report.flush();completed++;}double duration=rule::cpu()-start;if(!first)summary<<",";first=false;summary<<"{\"name\":\""<<fam<<"\",\"rules\":"<<idx.records<<",\"blocks\":"<<idx.blocks.size()<<",\"embeddings\":"<<idx.embeddings.size()<<",\"fourfold_stabilized_blocks\":"<<idx.stabilized<<",\"vacuum_polynomial_terms\":"<<idx.vacuum_poly.size()<<",\"setup_cpu_seconds\":"<<setup<<",\"samples\":"<<completed<<",\"sample_cpu_seconds\":"<<duration<<",\"maximum_support_seconds\":"<<maxseconds<<",\"rule_hits\":"<<total.rule_hits<<",\"maximum_rule_hits\":"<<maxhits<<",\"lookup_calls\":"<<lookups<<",\"lookup_misses\":"<<misses<<",\"cache_peak_entries\":"<<peakcache<<",\"gmp_cpu_seconds\":"<<gmp_cpu<<",\"gmp_products\":"<<gmp_products<<",\"gmp_max_limbs\":"<<max_limb<<",\"checksum_exact_Gram_bilinear\":\""<<checksum<<"\",\"sample_occupied_edge_classes\":{";bool ff=true;for(auto[k,v]:classes){if(!ff)summary<<",";ff=false;summary<<"\""<<k<<"\":"<<v;}summary<<"}}";summary.flush();cerr<<fam<<" sampled "<<completed<<" CPU "<<rule::cpu()<<endl;rule::guard();if(completed!=512)break;}rusage r{};getrusage(RUSAGE_SELF,&r);summary<<"],\"cpu_seconds\":"<<rule::cpu()<<",\"peak_rss_kib\":"<<r.ru_maxrss<<"}";return 0;}catch(string why){summary<<"],\"incomplete\":true,\"reason\":\""<<why<<"\"}";return 2;}}
